let shoppingPeriod='first';
function shoppingTrips(p){const cut=p.sessions.find(s=>s.start>=3)?.start??3,firstNeed={};for(const row of p.meals)for(const m of row)if(m.prepDay<cut)for(const[k,g]of Object.entries(recipes[m.id].ing))firstNeed[k]=(firstNeed[k]||0)+g*m.factor;
 const first=[],later=[];for(const b of p.basket){const grams=firstNeed[b.k]||0,packs=Math.min(b.packs,Math.ceil(grams/b.size-1e-10));if(packs)first.push({...b,grams,packs,cost:packs*b.price});if(b.packs>packs)later.push({...b,grams:Math.max(0,b.grams-grams-(packs*b.size-grams)),packs:b.packs-packs,cost:(b.packs-packs)*b.price})}return{cut,first,later,week:p.basket}}
function packageText(p){return p.k==='egg'&&!p.offer?`${p.packs*10} шт. · ${p.packs} уп. по 10`:`${p.packs} уп. × ${p.size} г`}
function usageText(p){return p.k==='egg'?`≈ ${(p.grams/50).toFixed(1)} яйца (расчёт по 50 г без скорлупы)`:`≈ ${Math.round(p.grams)} г`}
function shoppingCheckKey(k){return shoppingPeriod+':'+k}
function saveShoppingChecks(){try{localStorage.setItem(preferencesKey()+':checks',JSON.stringify({signature:JSON.stringify(plan.meals.map(r=>r.map(m=>[m.id,m.factor]))),keys:[...checked]}))}catch{}}
function restoreShoppingChecks(){try{const x=JSON.parse(localStorage.getItem(preferencesKey()+':checks'));if(x?.signature===JSON.stringify(plan.meals.map(r=>r.map(m=>[m.id,m.factor]))))checked=new Set(x.keys.filter(k=>typeof k==='string'))}catch{}}
function renderShoppingView(){const trips=shoppingTrips(plan),rows=trips[shoppingPeriod],total=rows.reduce((n,p)=>n+p.cost,0),count=rows.filter(p=>checked.has(shoppingCheckKey(p.k))).length;$('#screen').innerHTML=`<section class="enter shopping-page"><div class="eyebrow">Всё нужное, ничего лишнего</div><h1>Список покупок</h1><p class="intro">Можно докупить по ходу недели.<br>Остатки упаковок учтены.</p><div class="trip-selector" role="group" aria-label="Когда покупать">${[['first','Купить сейчас'],['later','Докупить · '+short[trips.cut]],['week','Вся неделя']].map(([k,t])=>`<button data-trip="${k}" aria-pressed="${shoppingPeriod===k}" class="${shoppingPeriod===k?'selected':''}">${t}</button>`).join('')}</div><details class="shopping-explainer"><summary>Как разделены покупки?</summary><p class="note">Первая покупка — для готовок до ${days[trips.cut].toLowerCase()}. Вторая — перед готовкой в ${days[trips.cut].toLowerCase()}. Для заготовок продукты покупаем до начала партии. Сумма обеих покупок равна недельной корзине; остатки первой переходят во вторую.</p></details><button class="outline-button" id="open-catalog">Цены и товары магазинов ↗</button><div class="shopping-summary"><div><span>Эта покупка</span><strong>${rub(total)}</strong><small>${plan.priceMode==='real'?'По загруженным ценам':'По демоценам'}</small></div><div class="shopping-counter"><b>${count}<small> / ${rows.length}</small></b><span>позиций отмечено</span></div><progress max="${Math.max(1,rows.length)}" value="${count}" aria-label="Прогресс покупок"></progress></div>${rows.length?'':'<p>Докупать ничего не нужно: хватит первой покупки.</p>'}${plan.stores.map(s=>{const list=rows.filter(p=>p.shop===s);return list.length?`<section class="list-store"><div class="shopping-store-heading"><h2>${shops[s][0]}</h2><span>${rub(list.reduce((n,p)=>n+p.cost,0))}</span></div>${list.map(p=>`<label class="product ${checked.has(shoppingCheckKey(p.k))?'is-bought':''}"><span class="product-icon">${foodEmoji[p.k]||'🛒'}</span><span class="product-name"><b>${p.name}</b><small>${packageText(p)}<br>${shoppingPeriod==='week'?'В рецепты за неделю':'Потребность покупки'}: ${usageText(p)}</small></span><span class="product-price">${rub(p.cost)}</span><input type="checkbox" aria-label="Куплено: ${p.name}" data-product="${p.k}" ${checked.has(shoppingCheckKey(p.k))?'checked':''}></label>${catalogOfferDetails(p)}`).join('')}</section>`:''}).join('')}<p class="note">Продукты распределяем между разными блюдами недели. Остаток упаковки можно оставить на следующую неделю.</p><button class="outline-button" id="export">↓ Скачать этот список</button><p class="note">${plan.priceMode==='real'?'Цены на момент загрузки.':'Демонстрационные цены.'} Недельный бюджет: ${rub(plan.total)}. Отметки сохраняются отдельно для каждого списка.</p></section>`;
 document.querySelectorAll('[data-trip]').forEach(b=>b.onclick=()=>{shoppingPeriod=b.dataset.trip;renderShoppingView()});$('#open-catalog').onclick=catalogGo;document.querySelectorAll('[data-product]').forEach(b=>b.onchange=()=>{const key=shoppingCheckKey(b.dataset.product);b.checked?checked.add(key):checked.delete(key);saveShoppingChecks();const y=window.scrollY;renderShoppingView();window.scrollTo(0,y);document.querySelector('[data-product="'+b.dataset.product+'"]')?.focus({preventScroll:true})});$('#export').onclick=()=>{const text=['НА НЕДЕЛЮ — '+({first:'Купить сейчас',later:'Докупить '+days[trips.cut],week:'Вся неделя'}[shoppingPeriod]),plan.priceMode==='real'?'Цены загруженных товаров':'Демонстрационные цены',...rows.map(p=>`${checked.has(shoppingCheckKey(p.k))?'[✓]':'[ ]'} ${p.name}: ${packageText(p)} — ${rub(p.cost)}, ${shops[p.shop][0]}`),'Итого: '+rub(total)].join('\n');if(navigator.userAgent.includes('NyambaAndroid')){location.href='nyamba-export:'+encodeURIComponent(text);return}const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Покупки.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
